-- Update images only. Abort atomically if a product was renamed or its image changed since review.
BEGIN;
CREATE TEMP TABLE reviewed_images (id integer, name text, expected_url text, new_url text) ON COMMIT DROP;
DO $$
DECLARE changed_count integer;
BEGIN
  UPDATE products p SET image_url = r.new_url FROM reviewed_images r
  WHERE p.id = r.id AND p.name = r.name AND p.image_url IS NOT DISTINCT FROM r.expected_url;
  GET DIAGNOSTICS changed_count = ROW_COUNT;
  IF changed_count <> 102 THEN
    RAISE EXCEPTION 'Image review expected 102 matching rows; found %. No changes committed.', changed_count;
  END IF;
END $$;
COMMIT;
